  [469182] = { nil, "Il tuo travestimento è fallito! Tieni un profilo basso per non danneggiare la linea temporale!", nil, 0xa26ee5dd, "mu" },
  [469183] = { "I totem evocati conferiscono un beneficio del loro elemento.", "I totem evocati conferiscono un beneficio del loro elemento.", 0x5d8a8187, 0x5d8a8187, "uu" },
  [469191] = { "Leggi una profezia dal tomo, che aumenta del $N1% la probabilità di colpo critico del tuo prossimo incantesimo o attacco non periodico.", "Probabilità di critico aumentata del $N1% per il tuo prossimo incantesimo o attacco.", 0x6ba2ca42, 0x1318f7a9, "uu" },
