  [469211] = { "Gli incantesimi di danno diretto hanno una probabilità di rendere istantaneo il prossimo famiglio che evochi entro $D1, senza consumare un frammento d'anima.", "Gli incantesimi a danno diretto hanno una probabilità di rendere istantaneo il prossimo famiglio che evochi entro $D1, senza consumare un frammento d'anima.", 0x41f371df, 0x41f371df, "uu" },
  [469220] = { "Il tuo prossimo incantesimo Evocazione: Imp, Evocazione: Ombra del Vuoto, Evocazione: Succube, Evocazione: Incubus, Evocazione: Vilsegugio o Evocazione: Vilguardia ha il tempo di lancio ridotto di $D1 e non costa frammenti d'anima né mana.", "Tempo di lancio delle evocazioni di Imp, Ombra del Vuoto, Succube, Incubo, Vilsegugio e Vilguardia ridotto di $D1. Costi in mana e in frammenti d'anima ridotti del $N2%.", 0x59404b53, 0xbe3d1d6a, "uu" },
  [469221] = { "Raccogli l'anima del demone che hai evocato, ottenendo un effetto che dura $D1. L'effetto viene annullato se viene evocato un qualsiasi demone.", nil, 0xe0855949, nil, "um" },
  [469222] = { nil, "Danni da fuoco aumentati del $N1%.", nil, 0x943a352e, "mu" },
