  [469227] = { nil, "Silenziato.", nil, 0x20816e34, "mu" },
  [469228] = { "Silenzia il nemico per $D1. Se usato su un bersaglio che sta lanciando un incantesimo, ne interrompe il lancio e gli impedisce di lanciare incantesimi di quella scuola di magia per $D2.", nil, 0x516ee526, nil, "um" },
  [469229] = { "Il tuo prossimo lancio di ⟦Curse of Tongues=Maledizione delle Lingue⟧ silenzierà il bersaglio per $D1. Se usata su un bersaglio che sta lanciando un incantesimo, ne interrompe il lancio e impedisce di lanciare incantesimi di quella scuola di magia per $D2.", "Il tuo prossimo lancio di ⟦Curse of Tongues=Maledizione delle Lingue⟧ silenzierà il bersaglio per $D1. Se usata su un bersaglio che sta lanciando un incantesimo, ne interrompe il lancio e impedisce di lanciare incantesimi di quella scuola di magia per $D2.", 0xa45b705c, 0xa45b705c, "uu" },
  [469230] = { "Danni fisici subiti ridotti del $N1%; la tua abilità Demon Charge è ora utilizzabile in combattimento e non ha tempo di recupero.", "Danni fisici subiti ridotti del $N1%; la tua abilità Demon Charge è ora utilizzabile in combattimento e non ha tempo di recupero.", 0x606cad2e, 0x606cad2e, "uu" },
  [469236] = { "Ogni volta che infliggi danni da arcano a un bersaglio, il tempo di recupero residuo di Prontezza di Spirito si riduce di $D1.", nil, 0x2f85cf03, nil, "um" },
  [469237] = { "Se hai il talento Bruciatura Migliorata, i bersagli colpiti dalla tua ⟦Blast Wave=Ondata di Fuoco⟧ ricevono anche $N1 accumuli di Vulnerabilità al Fuoco.", "Se hai il talento Bruciatura Migliorata, i bersagli colpiti dalla tua ⟦Blast Wave=Ondata di Fuoco⟧ ricevono anche $N1 accumuli di Vulnerabilità al Fuoco.", 0x51d0c21f, 0x51d0c21f, "uu" },
  [469238] = { "Mentre ⟦Ice Barrier=Barriera di Ghiaccio⟧ è attiva, i danni inflitti da incantesimi ed effetti di gelo aumentano fino a $N1.", "Mentre ⟦Ice Barrier=Barriera di Ghiaccio⟧ è attiva, i danni inflitti da incantesimi ed effetti di gelo aumentano fino a $N1.", 0x5320a64c, 0x5320a64c, "uu" },
  [469239] = { nil, "Danni di incantesimi ed effetti di gelo aumentati fino a $N1.", nil, 0xd3159f07, "mu" },
  [469260] = { "Perso nell'ebbrezza del combattimento, genera rabbia nel tempo.", "Perso nell'ebbrezza del combattimento, genera rabbia nel tempo.", 0x3b699f12, 0x3b699f12, "uu" },
  [469261] = { nil, "Immobilizzato.\nDanni aumentati del $N1%.\nCelerità aumentata del $N2%.\nInfligge danni pari al $N3% della salute massima ogni $D1.\nAlla morte infligge $N5 danni agli alleati circostanti.", nil, 0x97892e33, "mu" },
  [469262] = { "Attivalo nella ⟦Blackwing Lair=Fortezza dell'Ala Nera⟧ o nel ⟦Blackrock Mountain=Massiccio Roccianera⟧ per travestirti da Blackwing Technician.", "Travestimento da Blackwing Technician.", 0x6c403e22, 0x9618db14, "uu" },
  [469271] = { "Entra in sintonia con i cieli e sostituisci la tua Forma di Lunagufo con un aspetto più celestiale.", "Assume un aspetto astrale...", 0x7d88df02, 0xf73bad51, "uu" },
  [469277] = { "Inizia ad addomesticare una bestia perché diventi tua compagna. La tua armatura è ridotta del $N1% mentre ti concentri sull'addomesticamento della bestia per $D1. Se per qualsiasi motivo perdi l'attenzione della bestia, l'addomesticamento fallisce. Una volta addomesticata, la bestia sarà molto infelice e sleale. Prova a nutrire subito il famiglio per renderlo felice.", "Addomesticamento del famiglio.", 0x653847d0, 0xc7d3fce8, "uu" },
  [469301] = { "Inizia ad addomesticare una bestia perché diventi tua compagna. La tua armatura è ridotta del $N1% mentre ti concentri sull'addomesticamento della bestia per $D1. Se per qualsiasi motivo perdi l'attenzione della bestia, l'addomesticamento fallisce. Una volta addomesticata, la bestia sarà molto infelice e sleale. Prova a nutrire subito il famiglio per renderlo felice.", "Addomesticamento del famiglio.", 0x653847d0, 0xc7d3fce8, "uu" },
  [469306] = { "Inizia ad addomesticare una bestia perché diventi tua compagna. La tua armatura è ridotta del $N1% mentre ti concentri sull'addomesticamento della bestia per $D1. Se per qualsiasi motivo perdi l'attenzione della bestia, l'addomesticamento fallisce. Una volta addomesticata, la bestia sarà molto infelice e sleale. Prova a nutrire subito il famiglio per renderlo felice.", "Addomesticamento del famiglio.", 0x653847d0, 0xc7d3fce8, "uu" },
  [469320] = { "Scagli lava fusa contro il bersaglio, infliggendo $N1 danni da fuoco. Se la tua ⟦Flame Shock=Folgore del Fuoco⟧ è sul bersaglio, ⟦Lava Burst=Getto di Lava⟧ infligge un colpo critico.", nil, 0x675aa74d, nil, "um" },
  [469348] = { "Ti rende immune a effetti di disarmo.", nil, 0xa67c30b0, nil, "um" },
